mapper.update:
UPDATE outbox_event
SET status = 2,
    publish_time = #{publishTime},
    last_error = NULL,
    next_retry_time = NULL,
    updated_time = #{publishTime}
WHERE id = #{id}
  AND status = 1
  AND processing_token = #{processingToken}
  AND retry_count = #{retryCount}

UPDATE outbox_event
SET status = 0,
    processing_time = NULL,
    processing_token = NULL,
    retry_count = retry_count + 1,
    next_retry_time = #{nextRetryTime},
    last_error = #{lastError},
    updated_time = #{now}
WHERE id = #{id}
  AND status = 1
  AND processing_token = #{processingToken}
  AND retry_count = #{retryCount}
